  var a=OccupationalNarrativeAccessoryCatalog.forProfile(s.name(),c.name());var e=new CanonicalStartingEquipment(b.wornGarments(),b.inventoryObjectNames(),Optional.of(a),b.weaponNames(),b.ammunitionNames(),Optional.empty(),b.inventoryExpanders(),b.currencyStacks(),b.materialUnits());CanonicalStartingEquipmentPackingPolicy.requireValid(e);return e;
