 public static CanonicalLoadoutPlacementPlan placement(Subprofession s,CharacterClass c){return CivilianStartingEquipmentSupport.placement(equipment(s,c));}
 private static boolean male(CharacterClass c){return c==CharacterClass.LUCHADOR||c==CharacterClass.INTELECTUAL||c==CharacterClass.INDOMITO;}
 private static CanonicalStartingEquipment eq(List<ArmorPiece>w,List<String>o,List<String>we,List<String>a,int v,List<ArmorMaterial>mat,List<InventoryCompartmentType>ex){return new CanonicalStartingEquipment(w,o,Optional.empty(),we,a,Optional.empty(),ex,List.of(new CurrencyStack(CurrencyType.VALERITA,v)),mat);}
